@SuppressWarnings("unchecked")
void calc() {
    int[] ns = nextInts();
    int N = ns[0], M = ns[1];
    int[] A = nextInts();
    List<int[]>[] no = new List[200001];
    Arrays.setAll(no, i -> new ArrayList<>());
    for (int i = 0; i < M; i++) {
        int[] uv = nextInts();
        int u = uv[0] - 1, v = uv[1] - 1;
        if (A[u] < A[v]) no[A[u]].add(new int[] {u, v});
        if (A[u] > A[v]) no[A[v]].add(new int[] {v, u});
    }

    int[] dp = new int[N];
    Arrays.fill(dp, -1);
    dp[0] = 1;
    for (var n : no) {
        for (int[] uv : n) {
            int u = uv[0], v = uv[1];
            if (dp[u] > 0) dp[v] = Math.max(dp[v], dp[u] + 1);
        }
    }

    int maxScore = 0;
    for (int i = 0; i < N; i++) {
        if (dp[i] > 0) {
            int distinctCount = (int) Arrays.stream(A, 0, i + 1).distinct().count();
            maxScore = Math.max(maxScore, distinctCount);
        }
    }
    System.out.println(maxScore);
}
